--
-- Table structure for table `categories`
--

CREATE TABLE `categories` (
  `categoryTbl_id` int(11) NOT NULL,
  `section_id` int(11) NOT NULL,
  `category_name` varchar(100) NOT NULL,
  `category_slug` varchar(100) NOT NULL,
  `icon` varchar(254) NOT NULL,
  `description` text DEFAULT NULL,
  `category_status` enum('Active','Inactive','Deleted') DEFAULT 'Active',
  `date_added` datetime DEFAULT current_timestamp(),
  `record_time` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `categories`
--

INSERT INTO `categories` (`categoryTbl_id`, `section_id`, `category_name`, `category_slug`, `icon`, `description`, `category_status`, `date_added`, `record_time`) VALUES
(1, 1, 'Groceries', 'Groceries', '/category_icons/1759321305_images (1).png', 'Our Groceries section is stocked with fresh, authentic, and high-quality everyday essentials that keep your kitchen complete. From premium rice, grains, and flour to cooking oils, spices, seasonings, canned foods, beverages, and household staples, we bring you everything you need in one place. Carefully selected to meet your daily needs and traditional tastes, our groceries ensure you enjoy both convenience and authenticity with every meal.', 'Active', '2025-10-01 08:21:45', '2025-10-01 12:21:45'),
(2, 1, 'Cereals & Grains', 'cereals-grains', '/category_icons/1762563587_88CB5C79-F1E1-4498-B5BA-DBEABD514ABA.PNG', 'Discover the rich variety of African cereals and grains, including millet, maize, sorghum, rice, and oats. Perfect for preparing pap, fufu, and traditional meals, these staples are nutrient-packed and versatile. Ideal for both everyday cooking and cultural dishes, they bring authentic African flavors straight to your kitchen.', 'Active', '2025-10-01 15:01:50', '2025-11-08 00:59:47'),
(3, 1, 'Meat and Seafood', 'meatand-seafood', '/category_icons/1762559701_97BF52C7-A0DA-4930-89BE-64E92EAFA0AE.PNG', 'Bring home the taste of Africa with our premium fish and seafood selection. From dried catfish and stockfish to crayfish and prawns, these ingredients add depth and flavor to soups, stews, and sauces. Carefully sourced and preserved, they’re essential for traditional African recipes and family favorites.', 'Active', '2025-10-01 15:06:53', '2025-12-02 12:06:27'),
(4, 1, 'Meat and Poultry', 'meat-and-poultr', '/category_icons/1759346009_istockphoto-103975258-612x612.jpg', 'Enjoy authentic African cuts with our variety of fresh and preserved meat and poultry. From goat meat and beef to chicken and turkey, these protein-rich essentials are perfect for soups, grills, and stews. They deliver the hearty flavors and nourishment that complete every African dining experience', 'Active', '2025-10-01 15:13:29', '2025-10-01 19:13:29'),
(5, 1, 'Dairy and Beverages', 'dairy-and-beverage', '/category_icons/1759346352_images.png', 'Refresh and nourish with our dairy and beverage collection, featuring powdered milk, evaporated milk, yogurt drinks, malt, zobo, and traditional African refreshments. Perfect for breakfast, snacking, or entertaining, these wholesome products bring comfort, nutrition, and authentic African taste to your everyday meals and celebrations.', 'Active', '2025-10-01 15:19:12', '2025-10-01 19:19:12'),
(6, 2, 'African Dresses', 'african-dresses', '/category_icons/1762560068_FD946585-0B3D-44EC-A38A-AF5A6B4FA62A.PNG', 'A collection of stylish Ankara, Adire, and lace outfits designed for elegance, comfort, and cultural pride. Perfect for casual wear, parties, and special occasions.', 'Active', '2025-10-01 15:48:06', '2025-11-08 00:01:08'),
(7, 2, 'Footwear', 'footwear', '/category_icons/1762561641_243ddec0-27d0-4550-9434-03cbce4470cf.jpg', 'Trendy shoes, sandals, and slippers, blending modern style with African flair. Crafted for durability and comfort, ideal for everyday wear or events.', 'Active', '2025-10-01 15:49:47', '2025-11-08 00:27:21'),
(8, 2, 'Bags and Accessories', 'bags-and-accessorie', '/category_icons/1759348326_bags.jpg', 'Unique handbags, purses, jewelry, and belts to complete your look. Designed with creativity and African touch for fashionable statements.', 'Active', '2025-10-01 15:52:06', '2025-10-01 19:52:06'),
(9, 2, 'Men Wears', 'men-wear', '/category_icons/1762564608_Photoroom_024_20250419_181011.JPEG', 'Classic and contemporary African-inspired shirts, trousers, and native attires tailored for confidence, comfort, and cultural identity.', 'Active', '2025-10-01 15:56:44', '2025-11-08 01:16:48'),
(10, 2, 'Women Wears', 'women-wear', '/category_icons/1759348675_Women.png', 'Elegant gowns, skirts, blouses, and chic everyday outfits that highlight beauty, femininity, and African fashion excellence.', 'Active', '2025-10-01 15:57:55', '2025-10-01 19:57:55'),
(11, 3, 'Hair Extensions & Wigs', 'hair-extensions-wigs', '/category_icons/1762563877_f0aefcea-6167-4ea1-be18-98e00afa55c9.MP4', 'Step into elegance with our hand-braided lace-front wig, featuring soft, defined curls that mimic natural hair with unmatched realism.\r\n\r\n100% premium human hair and human hair blend\r\n\r\nLace-front design for a sophisticated natural look\r\n\r\nBreathable, lightweight cap for all-day comfort\r\n\r\nPre-plucked hairline for a natural look\r\n\r\nWhether you love curls, crave volume, or want a protective style that looks like your own hair — this wig delivers it all.\r\n\r\nStyle. Comfort. Confidence. Every strand, perfected.', 'Active', '2025-10-01 16:30:58', '2025-11-08 01:04:37'),
(12, 3, 'Hair Care Products', 'hair-care-products', '/category_icons/1759350871_images (1).png', 'Shampoos, conditioners, oils, and treatments that nourish, protect, and promote healthy, shiny hair.', 'Active', '2025-10-01 16:34:31', '2025-10-01 20:34:31'),
(13, 3, 'Skin Care & Facials', 'skin-care-facials', '/category_icons/1759351088_skin-care-icon-cosmetic-concept-vector-29049803.png', 'Cleansers, scrubs, facial kits, and moisturizers designed to keep your skin glowing and refreshed.', 'Active', '2025-10-01 16:38:08', '2025-10-01 20:38:08'),
(14, 3, 'Nails & Manicure Essentials', 'nails-manicure-essential', '/category_icons/1759351358_black-manicure-icons-depicting-nail-care-essentials-including-scissor_1263357-9989.jpg', 'Nail polish, acrylic sets, gels, and nail care tools for flawless, stylish nails.', 'Active', '2025-10-01 16:42:38', '2025-10-01 20:42:38'),
(15, 3, 'Makeup & Cosmetics', 'makeup-cosmetics', '/category_icons/1762564255_6F7CC3CE-972D-4F8A-8B44-E8D4B5181271.PNG', 'Foundations, powders, lipsticks, and beauty kits that enhance your natural look and glam', 'Active', '2025-10-01 16:44:45', '2025-11-08 01:10:55'),
(16, 4, 'Nail Services', 'nail-service', '/category_icons/1762562670_PHOTO-2025-11-04-11-55-08.jpg', 'Meet the nails everyone’s talking about — ultra-durable, easy to apply, and stunning from every angle.\r\n\r\nWhether you love classic nudes, bold chromes, or trendy French tips, our press-ons give you a perfect fit and a flawless finish — reusable, gentle, and always on trend.\r\n\r\n Lasts up to 14 days\r\n Reusable & waterproof\r\n Safe, cruelty-free adhesive\r\n\r\nTransform your nails in minutes — shop the collection now!', 'Active', '2025-10-07 03:39:48', '2025-11-08 00:44:30'),
(17, 4, 'Hair', 'hair', '/category_icons/1760720456_curlyhhw.jpg', '', 'Active', '2025-10-17 10:03:31', '2025-10-17 17:00:56'),
(18, 4, 'Facial', 'facial', '/category_icons/default.png', '', 'Inactive', '2025-10-17 10:04:22', '2026-02-24 10:04:08'),
(19, 1, 'FOOD COMBO', 'food-comb', '/category_icons/default.png', '', 'Active', '2026-01-16 20:05:29', '2026-01-17 01:05:29'),
