) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `products`
--

INSERT INTO `products` (`product_id`, `category_id`, `product_name`, `product_slug`, `description`, `brand`, `model`, `short_description`, `sku`, `price`, `discount_price`, `stock_quantity`, `is_featured`, `image_main`, `image_gallery`, `tags`, `color_options`, `size_options`, `status`, `date_added`, `product_tbl_record_time`) VALUES
(1, 1, '500g Scotch Bonnet Hot Pepper - Ata Rodo', 'scotch-bonnet-hot-pepper-ata-rodo-500g', 'Bring fiery flavor to your meals with our Scotch Bonnet Hot Pepper (Ata Rodo) 500g. Known for its bold heat and distinctive fruity aroma, ata rodo is a staple in African and Caribbean cooking. Perfect for soups, stews, sauces, and marinades, these fresh peppers add both spice and depth of flavor to your dishes. Carefully selected and packaged for freshness, our Scotch Bonnet ensures consistent quality in every pack. Whether you love extra heat or just a touch of spice, ata rodo is a must-have in every kitchen. Enjoy authentic taste with this 500g pack of pure freshness.', 'Queenzy', 'Queenzy pepper', 'Bring fiery flavor to your meals with our Scotch Bonnet Hot Pepper (Ata Rodo) 500g. Known for its bold heat and distinctive fruity aroma, ata rodo is a staple in African and Caribbean cooking', 'GRO-QUE-00001', 6.00, NULL, 50, 0, '62KkEgTCimages (14).jpeg', '[\"PnwheLUrimages (15).jpeg\",\"9A58RlYTimages (13).jpeg\",\"aLU6uFh2images (17).jpeg\",\"JFNXJeewimages (16).jpeg\"]', '', '', '', 'Active', '2025-10-01', '2025-10-01 12:32:04'),
(2, 1, 'YAM TUBER', 'Yam Tuber', 'Packed with essential nutrients like fiber, potassium, and complex carbohydrates, our yam tubers are ideal for health-conscious meals and satisfying comfort food. Whether you\'re preparing a hearty yam porridge, crispy yam fries, or smooth pounded yam, these tubers deliver consistent results every time.', 'Queenzy', 'Queenzy', 'Experience the rich, earthy flavor and versatility of our Fresh Yam Tuber, carefully harvested and selected for quality. Each tuber is firm, nutrient-dense, and naturally grown to preserve its authentic taste and texture. Perfect for boiling, frying, roasting, or pounding, yam is a staple in many traditional and modern recipes around the world.', 'GRO-QUE-00002', 6.00, NULL, 50, 0, 'TsLQBYJN1000043080.jpg', '[\"dv6Hz9Fe1000043083.jpg\",\"Vq2RR8vx1000043081.jpg\",\"HuEY87Rp1000043082.jpg\",\"tOSQjQLU1000043084.jpg\"]', '', '', 'S,M,L', 'Active', '2025-10-03', '2025-10-03 12:52:40'),
(3, 1, 'RICE 1kg', 'rice-1k', 'Our Premium Rice is sourced from trusted farms and carefully processed to ensure top-grade quality in every grain. Known for its long, fluffy texture and delightful aroma, it cooks evenly and pairs perfectly with a wide range of dishes from Jollof and fried rice to biryani and plain steamed rice.\r\nEach batch is thoroughly cleaned and sorted to be completely stone-free, chemical-free, and preservative-free, making it a healthy and safe choice for your kitchen. Whether you\'re cooking for the family or preparing for a celebration, this rice guarantees consistent results with every pot.', 'Queenzy', 'Queenzy', 'Enjoy our fluffy grains of naturally grown rice, perfect for daily meals and special recipes. 100% pure, chemical-free, and packed with rich aroma and flavor.', 'GRO-QUE-00003', 3.00, NULL, 50, 0, '5wqtkhPC1000043102.jpg', '[\"ib1HGKJJ1000043107.jpg\",\"r1i0CFry1000043106.jpg\",\"yeyGjiWs1000043104.jpg\",\"ofO7VwWA1000043103.jpg\"]', '', '1 kg', 'S,M,L', 'Active', '2025-10-03', '2025-11-28 10:59:13'),
(4, 4, '1kg Fresh Turkey Mid Wings', 'fresh-turkey-mid-wings-1kg', 'Enjoy the rich taste and satisfying texture of our Fresh Turkey Mid Wings, packed fresh and hygienically processed for your convenience. Each 1kg pack contains carefully cut mid-section wings, known for their balance of juicy meat and flavorful skin ideal for a wide range of dishes.\r\nWhether you\'re making spicy turkey wings, oven-roasted trays, soups, or barbecue, these wings cook beautifully and soak up marinades and spices with ease. Naturally high in protein and low in fat, they’re a great option for healthy, filling meals.', 'Queenzy', 'Queenzy', 'Tender, meaty, and full of flavor, our Fresh Turkey Mid Wings are perfect for grilling, baking, frying, or stewing. Cleaned and ready to cook, they’re a high-protein choice for hearty meals.', 'GRO-QUE-00004', 5.00, NULL, 60, 0, 'mfS6mitE1000045675.jpg', '[\"DP6ZNLPK1000045674.jpg\",\"YjPmexro1000045678.jpg\",\"MMDrO7vw1000045679.jpg\",\"G8JEmPU91000045677.jpg\"]', '', '', 'S,M,L,XL', 'Active', '2025-10-03', '2025-10-03 14:12:46'),
(5, 1, 'Fresh Tomatoes - 2kg', 'fresh-tomatoes-kg', 'Our Fresh Tomatoes are carefully harvested from trusted farms to ensure you get the best in taste and quality. Each tomato is firm, juicy, and naturally vine-ripened to deliver a perfect balance of sweetness and acidity.\r\nIdeal for a wide variety of culinary uses, from fresh salads and sandwiches to rich sauces, soups, and stews. These tomatoes add vibrant color and wholesome flavor to your meals. Packed with vitamins A and C, they’re not only delicious but also nutritious.', 'Queenzy', 'Queenzy', 'Bright, ripe, and bursting with flavor, our Fresh Tomatoes are handpicked at peak ripeness. Perfect for salads, sauces, stews, and everyday cooking.', 'GRO-QUE-00005', 11.00, NULL, 50, 0, 'ynoRiVjH1000045757.jpg', '[\"p9luQg6m1000045755.jpg\",\"AobBsmiW1000045758.jpg\",\"1u6MVK751000045754.jpg\",\"5T2OoZgn1000045760.jpg\"]', '', '', 'S,M', 'Active', '2025-10-03', '2025-11-28 10:59:52'),
(6, 3, 'Mackerel Titus - 1kg', 'mackerel-titus-200-400-1kg', 'Enjoy the delicious taste of our Fresh Mackerel Titus, carefully selected to weigh between 200 to 400 grams per fish. Known for its firm flesh and rich, oily flavor, this fish is ideal for a variety of cooking methods including grilling, frying, baking, or smoking.\r\nSustainably sourced and processed under hygienic conditions, our Mackerel Titus offers a nutritious source of omega-3 fatty acids, protein, and essential vitamins. Each 1kg pack contains multiple fresh fish, cleaned and ready to cook, making it convenient for family meals or special dishes.', 'Queenzy', 'Queenzy', 'High-quality, fresh Mackerel Titus fish weighing between 200-400g each. Perfect for grilling, frying, or smoking, delivering rich flavor and firm texture.', 'FIS-QUE-00006', 10.00, NULL, 50, 0, 'mzJqxvpw1000045776.jpg', '[\"gmpZyTHR1000045779.jpg\",\"3HoxogK51000045778.jpg\",\"tKlLjsLP1000045777.jpg\",\"sv6h41iy1000045775.jpg\"]', '', '', 'S,M', 'Active', '2025-10-03', '2025-12-02 01:14:07'),
(7, 3, 'Titus Sardine A L’huile Vegetale 125g', 'titus-sardine-a-lhuile-vegetale-125g', 'Enjoy the rich taste of the sea with Titus Sardines packed in vegetable oil. Each 125g can contains tender, high-quality sardines carefully preserved in light vegetable oil to maintain freshness and enhance flavor.\r\nIdeal for sandwiches, salads, pasta dishes, or straight from the can, these sardines are a nutritious source of protein, omega-3 fatty acids, and essential vitamins. The convenient packaging makes it easy to enjoy anytime, whether at home or on the go.', 'Queenzy', 'Queenzy', 'Delicious and convenient, these premium Titus sardines are packed in light vegetable oil for rich flavor and long-lasting freshness. Perfect for quick meals and snacks.', 'GRO-QUE-00007', 2.00, NULL, 50, 0, 'zvcZ4BLq1000045791.jpg', '[\"vTzH0mT71000045795.jpg\",\"6Kie2Y3P1000045794.jpg\",\"PyObE12V1000045792.jpg\",\"fi8EEJUB1000045793.jpg\"]', '', '', '', 'Active', '2025-10-03', '2025-10-03 14:11:37'),
(8, 3, 'Tilapia 800 - 2.5kg', 'Tilapia 800 - 2.5kg', 'Enjoy the rich taste and freshness of Tilapia 800 Up (2.5kg) a top-quality choice for seafood lovers. Each fish weighs 800g and above, giving you meaty, tender portions that are perfect for a variety of dishes.\r\nWhether you love your tilapia grilled, fried, steamed, or cooked in spicy Nigerian pepper soup, this product delivers great flavor and versatility. Packed with essential nutrients, protein, and Omega-3 fatty acids, it not only satisfies your taste buds but also supports a healthy diet.\r\nIdeal for home cooking, family gatherings, restaurants, and events. Tilapia 800 Up 2.5kg guarantees freshness, quality, and value for money. Conveniently packaged for easy storage and preparation, making it a must-have for every kitchen.', 'Queenzy', 'Queenzy', 'Fresh and premium-quality Tilapia, weighing 2.5kg (800g+ each). Perfect for grilling, frying, steaming, or making delicious soups and stews. Nutritious, tasty, and ideal for family meals.', 'GRO-QUE-00008', 16.00, NULL, 50, 0, 'eIunQaHK1000045815.jpg', '[\"pOeBLakH1000045816.jpg\",\"oHQfVPy31000045818.jpg\",\"5u7uJ3ph1000045814.jpg\",\"8dnOjEu01000045815.jpg\"]', '', '', 'S,M,L', 'Active', '2025-10-03', '2025-10-03 14:11:21'),
(9, 3, '155g Geisha Mackerel in tomato', 'geisha-mackerel-in-tomato-155g', 'Savor the delicious flavor of Geisha Mackerel in Tomato Sauce (155g) a trusted household favorite for generations. Made with carefully selected mackerel fish and blended with a rich, tangy tomato sauce, this canned meal is tasty, nutritious, and ready to eat.\r\nPacked with essential proteins, Omega-3 fatty acids, and vitamins, Geisha Mackerel is not only a satisfying dish but also a healthy option for the whole family. Its versatility makes it the perfect companion for rice, bread, yam, plantain, or pasta. Conveniently packaged in a 155g tin, it’s ideal for quick meals at home, lunch breaks, or travel.\r\nWith Geisha, you get consistent quality, authentic taste, and great value for money in every bite.', 'Queenzy', 'Queenzy', 'Enjoy the rich taste of Geisha Mackerel in Tomato Sauce (155g). A convenient, protein-packed meal option perfect with rice, bread, yam, or pasta.', 'FIS-QUE-00009', 2.00, NULL, 50, 0, '2YwKM2BS1000045824.jpg', '[\"WgeK8wiz1000045827.jpg\",\"EfKLtOfH1000045825.jpg\",\"YEiIV7sp1000045826.jpg\",\"vZvyo3QM1000045825.jpg\"]', '', '', 'M', 'Active', '2025-10-03', '2025-10-03 14:01:56'),
(10, 3, 'Stockfish 1kg', 'stockfish-1kg', 'Bring home the authentic flavor of Stockfish 1kg, a cherished ingredient in traditional Nigerian and West African cuisine. Made from carefully dried codfish, stockfish is prized for its rich taste, aroma, and ability to elevate local dishes.\r\nPacked with high-quality protein, vitamins, and minerals, this stockfish is a healthy choice for hearty family meals. It blends perfectly into soups and stews such as Egusi, Ogbono, Okra, and Vegetable soup, releasing a deep, savory flavor that enriches every bite.\r\nOur 1kg pack ensures excellent value, freshness, and convenience for both home cooking and restaurants. With its firm texture and long shelf life, it is a must-have kitchen staple for lovers of authentic traditional cooking.', 'Queenzy', 'Queenzy', 'Premium-quality Stockfish (1kg), rich in protein and authentic taste. Perfect for Nigerian soups and stews such as Egusi, Ogbono, and Okra.', 'FIS-QUE-00010', 37.00, NULL, 52, 0, '1lph7rdJ1000045837.jpg', '[\"C8Ym55NO1000045840.jpg\",\"TevY6ciE1000045841.jpg\",\"RqPQaAN31000045838.jpg\",\"DhZXa6f61000045839.jpg\"]', '', '', '', 'Active', '2025-10-03', '2025-10-03 14:10:13'),
(11, 4, 'Goat Meat - 1kg', 'goat-meat-1kg', 'Experience the bold, authentic taste of Goat Meat 1kg, a favorite in Nigerian and African kitchens. Known for its unique flavor and tender texture, goat meat is the star ingredient in popular meals such as Goat Meat Pepper Soup, Jollof Rice with Goat Meat, stews, grills, and festive dishes.\r\nNaturally rich in protein, iron, and essential nutrients, goat meat is a healthy alternative to beef or lamb, offering a delicious balance of taste and nutrition. Our 1kg pack comes freshly cut, cleaned, and ready for cooking, saving you time while ensuring top quality.\r\nWhether for everyday meals, family gatherings, or special celebrations, goat meat adds that extra touch of richness and flavor to your table.', 'Queenzy', 'Queenzy', 'Fresh and tender Goat Meat (1kg), perfect for pepper soup, stews, grills, and traditional Nigerian dishes. Rich in flavor, high in protein, and freshly cut for your convenience.', 'MEA-QUE-00011', 9.00, NULL, 50, 0, '1gosJEd1Screenshot 2026-01-15 at 19.01.55.png', '[\"9KL5yChG1000045842.jpg\",\"mVmumoZ51000045845.jpg\",\"pNILaJzs1000045844.jpg\",\"6mf5yrtG1000045846.jpg\"]', '', '', '', 'Active', '2025-10-03', '2026-01-18 03:04:20'),
(12, 4, 'Tripe(Saki) -1kg', 'tripesaki-1kg', 'Enjoy the rich, savory taste of Tripe (Saki) 1kg, a popular delicacy in Nigerian and African cuisine. Known for its chewy texture and distinctive flavor, tripe (cow stomach) is a versatile ingredient that enhances soups, stews, and pepper soup with unmatched depth.\r\nPacked with protein, vitamins, and essential minerals, saki is both nutritious and satisfying. It pairs perfectly with dishes like Egusi, Ogbono, Vegetable soup, and traditional pepper soup. Our tripe comes freshly cleaned, cut, and ready to cook, making meal preparation easy and convenient.\r\nIdeal for home cooking, parties, or festive meals, this 1kg pack offers great value and authentic taste for lovers of traditional dishes.', 'Queenzy', 'Queenzy', 'Freshly cleaned Tripe (Saki) 1kg, perfect for Nigerian soups and stews such as pepper soup, egusi, ogbono, and vegetable soup. Tasty, protein-rich, and ready to cook.', 'MEA-QUE-00012', 5.00, NULL, 50, 0, 'CVGzpQHm1000045851.jpg', '[\"s8lE9Thi1000045850.jpg\",\"hISWLnO21000045847.jpg\",\"39BK7v581000045848.jpg\",\"dopstbP01000045849.jpg\"]', '', '', '', 'Active', '2025-10-03', '2025-10-03 14:26:33'),
(13, 4, 'Frozen Chicken Gizzard -1kg', 'chicken-gizzard-1kg', 'Known for its rich flavor and versatility, chicken gizzard is ideal for stir-fry recipes, jollof rice, stews, skewers (stick meat), and snacks.\r\nNaturally high in protein, vitamins, and minerals, it supports a healthy, balanced diet while adding a delightful taste to your meals. Each pack is freshly cleaned, trimmed, and ready to cook, saving you time and effort in the kitchen.\r\nPerfect for home use, parties, and catering, Chicken Gizzard guarantees premium quality, freshness, and great value for money.', 'Queenzy', 'Queenzy', 'Fresh and tender Chicken Gizzard, perfect for stir-fries, stews, grills, and party rice. High in protein, rich in flavor, and freshly cleaned for your convenience.', 'MEA-QUE-00013', 4.00, NULL, 50, 0, 'c8ZZYUzQ1000048276.jpg', '[\"38GsCeyE1000048279.jpg\",\"YU26arDH1000048278.jpg\",\"OEevDQBp1000048277.jpg\",\"GsCbpted1000048275.jpg\"]', '', '', '', 'Active', '2025-10-04', '2025-10-04 20:24:30'),
(14, 5, '400g  Peak Milk', 'peak-milk', 'Enjoy the creamy goodness of Peak Milk, Nigeria’s trusted dairy brand for generations. Made from pure, high-quality cow’s milk, Peak Milk is enriched with essential nutrients such as calcium, protein, and vitamins A, D, and B12, all vital for strong bones, sharp minds, and sustained energy\r\nWhether you’re making a warm cup of tea, a delicious bowl of cereal, baking your favorite treats, or preparing nutritious smoothies, Peak Milk delivers a rich, creamy taste every time.\r\nAvailable in evaporated, powdered, and filled milk options, Peak Milk is perfect for both home and commercial use. With its consistent quality and unbeatable flavor, it remains the go-to choice for families who value nourishment and taste in every drop.', 'Queenzy', 'Queenzy', 'Rich, creamy, and nourishing Peak Milk. Packed with essential vitamins and minerals for healthy growth and energy. Perfect for tea, coffee, cereal, and baking.', 'DAI-QUE-00014', 9.00, NULL, 50, 0, 'u6wRX7zn1000048280.jpg', '[]', '', '', '', 'Active', '2025-10-04', '2025-10-04 20:28:21'),
(15, 5, 'Bournvita 500g', 'bournvita-500g', 'Start your day with the rich chocolate-malt goodness of Cadbury Bournvita, the energy drink that fuels your body and mind. Made from malted barley, cocoa, and essential nutrients, Bournvita provides the perfect balance of taste and nourishment for growing children and busy adults alike.\r\nEnriched with vitamins (A, B, C, D) and minerals like calcium and iron, it helps support strong bones, mental alertness, and overall vitality. Just mix with hot or cold milk for a creamy, energizing drink that keeps you active all day.\r\nWhether for breakfast, school breaks, or evening refreshment, Bournvita delivers strength, energy, and that irresistible chocolate flavor every family loves.', 'Queenzy', 'Queenzy', 'Delicious and nutritious Bournvita 500g — a chocolate malt drink packed with vitamins and minerals for strength, energy, and mental alertness. Perfect for both kids and adults.', 'DAI-QUE-00015', 7.00, NULL, 50, 0, 'W0E2Eyl41000048285.jpg', '[\"E2ERH3y21000048284.jpg\",\"bXEVUnfO1000048283.jpg\",\"eYxtIrdy1000048281.jpg\",\"9TQDcY751000048282.jpg\"]', '', '', '', 'Active', '2025-10-04', '2025-10-04 20:39:28'),
(16, 5, '400g Nestle Milo', '400g Milo Nestle', 'Fuel your active lifestyle with Nestlé Milo, the world-renowned chocolate malt drink loved by families everywhere. Made from the natural goodness of malt, milk, and cocoa, Milo provides lasting energy and nourishment to keep you strong and alert all day.\r\nEnriched with Vitamins B2, B3, B6, B12, C, and D, plus calcium, iron, and phosphorus, Milo supports healthy growth, bone strength, and vitality. Simply mix with hot or cold milk or water for a rich, chocolatey drink that powers up your mornings or refreshes your evenings.\r\nIdeal for children, students, and adults who need sustained energy, Nestlé Milo delivers the perfect blend of taste and nutrition for the whole family.', 'Queenzy', 'Queenzy', 'Energize your day with Nestlé Milo, the delicious chocolate malt drink packed with essential vitamins and minerals for growth, strength, and energy. Perfect for both kids and adults.', 'DAI-QUE-00016', 7.00, NULL, 50, 0, 'QKKXxW9g1000048290.jpg', '[\"wfpdldGE1000048289.jpg\",\"0OuL2MIg1000048288.jpg\",\"6npstRYg1000048287.jpg\",\"ihprHVwE1000048286.jpg\"]', '', '', '', 'Active', '2025-10-04', '2025-10-04 20:45:20'),
(17, 5, '1kg Cerelac Wheat With Milk', 'cerelac-wheat-with-milk-12months-1kg', 'Give your baby the best start with Nestlé Cerelac Wheat with Milk, a nutritious and convenient infant cereal designed to support healthy growth and development. Made from high-quality wheat grains and milk, this smooth, creamy cereal provides a rich source of energy, protein, vitamins, and minerals for your growing baby.\r\nFortified with Iron+, Zinc, Vitamins A, C, and D, and other key nutrients, Cerelac helps support brain development, strong immunity, and healthy bones. It’s easy to digest, gentle on your baby’s tummy, and quick to prepare, just add clean water to make a wholesome meal.\r\nPerfect for weaning babies (6 months and above), Cerelac Wheat with Milk is trusted by mothers worldwide for its taste, nutrition, and reliability in every spoonful.', 'Queenzy', 'Queenzy', 'Nutritious and delicious Nestlé Cerelac Wheat with Milk. An instant cereal specially made for babies from 6 months and above. Enriched with essential vitamins, minerals, and milk for healthy growth and development.', 'GRO-QUE-00017', 10.00, NULL, 50, 0, 'JvotqPTx1000048293.jpg', '[\"qIN1ax4f1000048292.jpg\",\"NF5Pol8K1000048293.jpg\",\"ZUKkuxhy1000048291.jpg\",\"FjLO28W21000048292.jpg\"]', '', '', '', 'Active', '2025-10-04', '2025-10-04 20:50:41'),
