(362, 3, 'Hake fish 5kg', 'hake-fish', 'It’s a popular choice for frying, baking, grilling, or making stews. In African, Spanish, and Portuguese cuisines, it’s often deep-fried or cooked in spicy tomato sauces. In the UK, it’s also a great alternative to cod for fish and chips because it’s cheaper and just as tasty.\r\n\r\nNutritionally, hake is high in protein, low in fat, and a good source of vitamins B6 and B12, phosphorus, and selenium.', 'frozen', 'fish', 'It’s a popular choice for frying, baking, grilling, or making stews. In African, Spanish, and Portuguese cuisines, it’s often deep-fried or cooked in spicy tomato sauces. In the UK, it’s also a great alternative to cod for fish and chips because it’s cheaper and just as tasty.\r\n\r\nNutritionally, hake is high in protein, low in fat, and a good source of vitamins B6 and B12, phosphorus, and selenium.', 'FIS-FRO-00359', 34.00, NULL, 50, 0, 't25NToXNPhotoroom_000_20251108_175743 2.jpeg', '[]', '', '', '', 'Active', '2025-11-08', '2025-11-08 18:19:28'),
(363, 1, 'Hake fish 10kg', 'hake-fish-1kg', 'It’s a popular choice for frying, baking, grilling, or making stews. In African, Spanish, and Portuguese cuisines, it’s often deep-fried or cooked in spicy tomato sauces. In the UK, it’s also a great alternative to cod for fish and chips because it’s cheaper and just as tasty.\r\n\r\nNutritionally, hake is high in protein, low in fat, and a good source of vitamins B6 and B12, phosphorus, and selenium.', 'frozen', 'fish', 'It’s a popular choice for frying, baking, grilling, or making stews. In African, Spanish, and Portuguese cuisines, it’s often deep-fried or cooked in spicy tomato sauces. In the UK, it’s also a great alternative to cod for fish and chips because it’s cheaper and just as tasty.\r\n\r\nNutritionally, hake is high in protein, low in fat, and a good source of vitamins B6 and B12, phosphorus, and selenium.', 'GRO-FRO-00363', 61.99, NULL, 50, 0, 'QDnUgvn0Photoroom_000_20251108_175743 2.jpeg', '[\"a6NokS6GPhotoroom_003_20251108_175743.jpeg\"]', '', '', '', 'Active', '2025-11-08', '2025-11-08 18:23:16'),
