(367, 3, 'Titus or Scumbia 20kg', 'titus-or-scumbia-20kg71', 'Flavor lovers, this one’s for you! \r\nMackerel — known as Titus or Scumbia — is the fish that brings bold taste and real energy to your plate!\r\n\r\nRich, oily, and full of flavor\r\nHigh in protein & Omega-3s — good for your heart, brain, and body\r\nPerfect for grilling, frying, stewing, or smoking\r\n Loved across Africa and beyond for its unbeatable taste and nutrition\r\n\r\nFrom your favorite street meals to home-cooked classics —\r\nTitus (Scumbia) makes every bite unforgettable! \r\n\r\nFresh. Flavorful. Full of life — That’s Mackerel!', 'frozen', 'fish', 'Flavor lovers, this one’s for you! \r\nMackerel — known as Titus or Scumbia — is the fish that brings bold taste and real energy to your plate!', 'FIS-FRO-00366', 71.50, NULL, 50, 0, 'DbwgB14MIMG_1927.jpg', '[\"OAKmB6nPIMG_1928.jpg\"]', '', '', '', 'Active', '2025-11-08', '2025-11-08 18:51:59'),
(368, 3, 'Titus or Scumbia 10kg', 'titus-or-scumbia-0kg', 'Flavor lovers, this one’s for you! \r\nMackerel — known as Titus or Scumbia — is the fish that brings bold taste and real energy to your plate!\r\n\r\nRich, oily, and full of flavor\r\nHigh in protein & Omega-3s — good for your heart, brain, and body\r\nPerfect for grilling, frying, stewing, or smoking\r\n Loved across Africa and beyond for its unbeatable taste and nutrition\r\n\r\nFrom your favorite street meals to home-cooked classics —\r\nTitus (Scumbia) makes every bite unforgettable! \r\n\r\nFresh. Flavorful. Full of life — That’s Mackerel!', 'frozen', 'fish', 'Flavor lovers, this one’s for you! \r\nMackerel — known as Titus or Scumbia — is the fish that brings bold taste and real energy to your plate!', 'FIS-FRO-00368', 35.50, NULL, 50, 0, 'XccXmCrhIMG_1927.jpg', '[]', '', '', '', 'Active', '2025-11-08', '2025-11-08 18:59:23'),
