--
-- Table structure for table `sections`
--

CREATE TABLE `sections` (
  `id` int(11) NOT NULL,
  `section_name` varchar(100) NOT NULL,
  `section_slug` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `section_status` enum('Active','Inactive','Deleted') DEFAULT 'Active',
  `date_added` datetime DEFAULT current_timestamp(),
  `record_time` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `sections`
--

INSERT INTO `sections` (`id`, `section_name`, `section_slug`, `description`, `section_status`, `date_added`, `record_time`) VALUES
(1, 'Queenzy African Store', 'queenzyafrican-store', 'Our African Store specializes in selling food, grocery items, beauty products, and cultural goods that are commonly consumed or used in African households. We are positioned to serve the African diaspora as well as anyone interested in authentic African ingredients and lifestyle products.', 'Active', '2025-09-19 13:16:26', '2025-09-19 17:17:00'),
(2, 'Queenzy Fashion Store', 'queenzyfashion-store', 'Step into elegance with Queenzy Fashion Store – your one-stop destination for premium African-inspired outfits, stylish footwear, trendy bags, and accessories that speak confidence. We blend creativity with quality to give you unique fashion pieces tailored for every occasion. Whether you’re looking for everyday essentials or standout designs, Queenzy ensures you look your best while enjoying unbeatable value.', 'Active', '2025-09-29 08:47:42', '2025-09-29 12:47:42'),
(3, 'Queenzy Beauty and Hair Store', 'queenzy-beauty-and-hair-stor', 'Step into the world of elegance with Queenzy Beauty and Hair Store — your one-stop destination for premium beauty and hair essentials. From top-quality wigs, hair extensions, and styling tools to trusted skincare and make-up products, we provide everything you need to look and feel your best. Whether you’re going for a bold new look, enhancing your natural glow, or keeping your hair healthy and stylish, Queenzy is here to deliver quality, confidence, and beauty you can trust.', 'Active', '2025-09-29 09:18:37', '2025-09-29 13:18:37'),
(4, 'Queenzy Salon', 'queenzy-salo', 'At Queenzy Salon, beauty meets relaxation. We specialize in professional nail care, facials, hair styling, and make-up services, all designed to bring out your natural glow. Whether you’re preparing for a special event, refreshing your look, or pampering yourself, our skilled stylists and beauticians ensure you step out looking and feeling your absolute best.', 'Active', '2025-09-29 09:21:02', '2025-09-29 13:21:02');

