INSERT INTO `testimonials` (`id`, `name`, `location`, `photo`, `message`, `testimonial_created_at`) VALUES
(1, 'Chloe Bennett', 'Brixton, London', 'assets/images/testimonial/1.jpg', 'Absolutely love their Ankara designs! I’ve been shopping here for 6 months now and every outfit turns heads.', '2025-08-05 19:56:53'),
(2, 'Amara Olatunde', 'Peckham, South London', 'assets/images/testimonial/2.jpg', 'Queenzy’s braid salon is the best I’ve visited in the UK. Fast service, great atmosphere, and flawless braids!', '2025-08-05 19:56:53'),
(3, 'Grace Thompson', 'Manchester City Centre', 'assets/images/testimonial/3.jpg', 'I ordered a gele and custom-made bag online, and delivery was super quick. The quality is top-notch!', '2025-08-05 19:56:53'),
(4, 'Ebuka Nwosu', 'Hackney, London', 'assets/images/testimonial/4.jpg', 'Shopping for African groceries has never been easier. Everything I need is always in stock and fresh.', '2025-08-05 19:56:53'),
(5, 'Maya Williams', 'Tooting, London', 'assets/images/testimonial/5.jpg', 'The makeup selection at Queenzy is unmatched. I always find shades that suit my skin tone.', '2025-08-05 19:56:53'),
(6, 'Tomi Adebanjo', 'Leeds City Centre', 'assets/images/testimonial/6.jpg', 'Had my hair done last week and I’ve never gotten so many compliments. Thank you, Queenzy Salon!', '2025-08-05 19:56:53'),
(7, 'Rachel Mensah', 'Stratford, East London', 'assets/images/testimonial/7.jpg', 'I love how easy the online store is to navigate. Plus, customer service is excellent.', '2025-08-05 19:56:53'),
(8, 'Yemi Ajayi', 'Birmingham', 'assets/images/testimonial/8.jpg', 'Queenzy’s African print shoes are a vibe! They’re bold, colorful, and comfortable.', '2025-08-05 19:56:53'),
(9, 'Nina Okafor', 'Croydon, London', 'assets/images/testimonial/9.jpg', 'The pedicure service was so relaxing. Definitely coming back with my sisters next time.', '2025-08-05 19:56:53'),
(10, 'Diane Clarke', 'Notting Hill, London', 'assets/images/testimonial/10.jpg', 'I always find something new whenever I visit the store. Their fashion collection is beautiful and affordable.', '2025-08-05 19:56:53');

